class PrView {
  final String? repoId;
  final int? number;
  final String? url;
  final String state;
  final String? title;
  final String? baseRefName;
  final String? checkStatus;
  final List<PrCheckView> checks;
  final String? reviewStatus;
  final bool? mergeReady;
  final bool? hasConflicts;
  final int? commentCount;
  final int? unresolvedReviewThreadCount;
  final PrQueueView? mergeQueue;

  /// `Checks (X/Y passed)`.
  final String checksHeader;
  final bool checksExpanded;

  /// The queue state an action's PR shows (`mergeQueueForActionPr`).
  final PrQueueView? actionQueue;

  const PrView({
    this.repoId,
    this.number,
    this.url,
    required this.state,
    this.title,
    this.baseRefName,
    this.checkStatus,
    required this.checks,
    this.reviewStatus,
    this.mergeReady,
    this.hasConflicts,
    this.commentCount,
    this.unresolvedReviewThreadCount,
    this.mergeQueue,
    required this.checksHeader,
    required this.checksExpanded,
    this.actionQueue,
  });

  @override
  int get hashCode =>
      repoId.hashCode ^
      number.hashCode ^
      url.hashCode ^
      state.hashCode ^
      title.hashCode ^
      baseRefName.hashCode ^
      checkStatus.hashCode ^
      const DeepCollectionEquality().hash(checks) ^
      reviewStatus.hashCode ^
      mergeReady.hashCode ^
      hasConflicts.hashCode ^
      commentCount.hashCode ^
      unresolvedReviewThreadCount.hashCode ^
      mergeQueue.hashCode ^
      checksHeader.hashCode ^
      checksExpanded.hashCode ^
      actionQueue.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PrView &&
          runtimeType == other.runtimeType &&
          repoId == other.repoId &&
          number == other.number &&
          url == other.url &&
          state == other.state &&
          title == other.title &&
          baseRefName == other.baseRefName &&
          checkStatus == other.checkStatus &&
          const DeepCollectionEquality().equals(checks, other.checks) &&
          reviewStatus == other.reviewStatus &&
          mergeReady == other.mergeReady &&
          hasConflicts == other.hasConflicts &&
          commentCount == other.commentCount &&
          unresolvedReviewThreadCount == other.unresolvedReviewThreadCount &&
          mergeQueue == other.mergeQueue &&
          checksHeader == other.checksHeader &&
          checksExpanded == other.checksExpanded &&
          actionQueue == other.actionQueue;
}

